mapper.select:
select rpi.PROD_NAME prodName, dpn.PROD_REGIST_NO prodRegistNo, dpn.DATA_STATUS dataStatus, dpn.NOCREATE_REASON nocreateReason, dpn.REPORT_ISSUE_DATE reportIssueDate, dpn.IS_SALES_AGENCY isSalesAgency, dpn.DATA_SOURCE, dpn.UPDATE_TIME updateTime, dpn.UPDATE_USER updateUser from DIS_PROD_NOCREATE dpn left join V_REP_PROD_INFO rpi on dpn.PROD_REGIST_NO = rpi.PROD_RE
AND dpn.PROD_REGIST_NO in
#{item}
AND dpn.PROD_ID in
#{item}
AND dpn.DATA_STATUS=#{dataStatus}
AND dpn.REPORT_ISSUE_DATE >= TO_DATE(#{reportIssueDateStart},'YYYY-MM-DD')
AND dpn.REPORT_ISSUE_DATE <= TO_DATE(#{reportIssueDateEnd},'YYYY-MM-DD')
order by dpn.UPDATE_TIME desc

mapper.delete:
update DIS_PROD_NOCREATE
set DATA_STATUS = 'D',
UPDATE_TIME =#{updateTime,jdbcType=TIMESTAMP},
UPDATE_USER =#{updateUser,jdbcType=VARCHAR}
where PROD_REGIST_NO = #{prodRegistNo,jdbcType=VARCHAR}

mapper.select:
select count (1) from DIS_PROD_NOCREATE where
DATA_STATUS = 'E' and
PROD_REGIST_NO = #{prodRegistNo,jdbcType=VARCHAR}
